INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20201, 'Ezekiel 34:3', 'Ezekiel', 34, 3, '&nbsp;تاسو د دې پئ څښئ، او د دې د وړۍ نه ځانله جامې جوړَوئ او د خوښې ګډورى ترې نه حلالوئ، خو تاسو خپله رمه نۀ څروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20202, 'Ezekiel 34:4', 'Ezekiel', 34, 4, '&nbsp;تاسو د کمزورو ګډو خيال نۀ کولو او نۀ مو د بيمارانو دارو کول، او نۀ مو د زخمى شوو مرهم پټۍ کوله. تاسو ورک شوې واپس نۀ راوستل، او نۀ مو د ورک شوو لټون کولو. تاسو په هغوئ په سختۍ او د ظلم حکومت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20203, 'Ezekiel 34:5', 'Ezekiel', 34, 5, '&nbsp;نو هغه ګډې خوَرې شوې ځکه چې د هغوئ شپونکے نۀ وو، او کله چې هغه خورې ورې شوې نو د ځنګلى ځناورو د خوراک شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20204, 'Ezekiel 34:6', 'Ezekiel', 34, 6, '&nbsp;زما ګډې په ټولو غرونو او اوچتو غونډو سرګردانه وګرځېدلې. هغوئ په ټوله زمکه باندې خوَرې شوې، او چا هم نۀ د هغوئ لټون وکړو او نۀ يې وکتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20205, 'Ezekiel 34:7', 'Ezekiel', 34, 7, '&nbsp;نو په دې وجه اے شپونکو، د مالِک خُدائ کلام واورئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20206, 'Ezekiel 34:8', 'Ezekiel', 34, 8, '&nbsp;زما دې په خپل ذات قسم وى، مالِک قادر مطلق خُدائ فرمائى، ځکه چې زما د ګډو ښۀ شپونکے نشته نو په دې وجه لوټ شوې او د ټولو ځنګلى ځناورو د خوراک شوې، ځکه چې زما شپونکو زما د رمې لټون ونۀ کړو او زما د رمې په ځائ يې د خپل ځان خيال وساتلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20207, 'Ezekiel 34:9', 'Ezekiel', 34, 9, '&nbsp;نو په دې وجه اے د قوم شپونکو، د مالِک خُدائ کلام واورئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20208, 'Ezekiel 34:10', 'Ezekiel', 34, 10, '&nbsp;مالِک قادر مطلق خُدائ دا فرمائى چې، زۀ اوس د دې شپونکو خلاف يم او هغوئ به زۀ د خپلو ګډو دپاره ذمه وار وګرځوم. زۀ به هغوئ د خپلو ګډو د شپونتوب نه لرې کړم نو داسې به شپونکى نور خپل ځانونه نۀ شى مړولے. زۀ به خپلې ګډې د هغوئ د خُلو نه بچ کړم، او هغوئ به نور د دوئ خوراک نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20209, 'Ezekiel 34:11', 'Ezekiel', 34, 11, '&nbsp;”مالِک قادر مطلق خُدائ فرمائى چې، زۀ به په خپله د خپلو ګډو لټون وکړم او هغوئ به راپېدا کړم او د هغوئ خيال به ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20210, 'Ezekiel 34:12', 'Ezekiel', 34, 12, '&nbsp;لکه څنګه چې شپونکى د خپلو ګډو سره وى او د خپلو خوَرو ګډو په تلاش کښې وى، نو هم داسې به زۀ هم د خپلو ګډو په تلاش کښې يم. زۀ به هغوئ د هغه ټولو ځايونو نه بچ کړم چرته چې هغوئ د تيارې او د وريځې په ورځ خوَرې ورې شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20211, 'Ezekiel 34:13', 'Ezekiel', 34, 13, '&nbsp;زۀ به هغوئ د نورو قومونو نه راوکاږم او د نورو مُلکونو نه به يې راغونډ کړم، او زۀ به هغوئ خپل مُلک ته واپس راولم. هغوئ به زۀ د بنى اِسرائيلو په غرونو، او سيندونو په غاړه او د مُلک په ټولو آبادو ځايونو کښې وڅروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20212, 'Ezekiel 34:14', 'Ezekiel', 34, 14, '&nbsp;زۀ به هغوئ په ښۀ شنو ځايونو کښې وڅروم، او د بنى اِسرائيلو د غرونو لوړې څوکې به د هغوئ د څرېدو ځائ وى. او هلته به هغوئ په ښۀ شنو واښو کښې څملى، او هغوئ د بنى اِسرائيلو د غرونو په شنو واښو کښې وڅريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20213, 'Ezekiel 34:15', 'Ezekiel', 34, 15, '&nbsp;زۀ به په خپله د خپلو ګډو شپون يم او هغوئ له به آرام ورکړم، مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20214, 'Ezekiel 34:16', 'Ezekiel', 34, 16, '&nbsp;زۀ به د ورکو شوو ګډو لټون وکړم او بې‌لارې شوې ګډې به راواپس کړم. زۀ به د زخمى شوو مرهم پټۍ وکړم او کمزورو له به طاقت ورکړم، خو حرصناکې او مضبوطې به هلاکې کړم. زۀ به په اِنصاف سره د ګډو شپونتوب وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20215, 'Ezekiel 34:17', 'Ezekiel', 34, 17, '&nbsp;ترڅو چې ستاسو خبره ده اے زما رَمې، مالِک قادر مطلق خُدائ داسې فرمائى، زۀ به په خپله د يو ګډ او بل ګډ په مينځ کښې فېصله وکړم، او د ګډانو او د چېلو په مينځ کښې به عدالت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20216, 'Ezekiel 34:18', 'Ezekiel', 34, 18, '&nbsp;ولې دا ستاسو دپاره کافى نۀ ده چې په ښه ګياه کښې وڅرېږئ؟ ولې تاسو به نوره پاتې ګياه د پښو لاندې کوئ څۀ؟ ولې دا ستاسو دپاره کافى نۀ ده چې پاکې اوبۀ وڅښئ؟ ولې تۀ به نورې پاتې اوبۀ په پښو سره خړوئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20217, 'Ezekiel 34:19', 'Ezekiel', 34, 19, '&nbsp;ولې زما رمه به هغه ګياه خورى چې تاسو د پښو لاندې کړې وى او هغه اوبۀ به څښى چې تاسو د پښو سره خړې کړې دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20218, 'Ezekiel 34:20', 'Ezekiel', 34, 20, '&nbsp;نو په دې وجه هغوئ ته، مالِک قادر مطلق خُدائ فرمائى چې، ګورئ، زۀ په خپله به د څُرب ګډ او مانده ګډ په مينځ کښې عدالت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20219, 'Ezekiel 34:21', 'Ezekiel', 34, 21, '&nbsp;ځکه چې تاسو څربه ګډو، په خپلو اوږو او پتونونو باندې ټولې مانده ګډې ديکه کړې، او په خپلو ښکرونو سره مو ډغرې ورکړې، تر دې چې تاسو هغوئ خورې ورې کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20220, 'Ezekiel 34:22', 'Ezekiel', 34, 22, '&nbsp;نو زۀ به خپله رمه بچ کړم، او هغوئ به نور نۀ تالا والا کيږى. زۀ به د يوې ګډې او د بلې ګډې په مينځ کښې عدالت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20221, 'Ezekiel 34:23', 'Ezekiel', 34, 23, '&nbsp;زۀ به په هغوئ يو شپونکے مقرر کړم، زما خِدمتګار داؤد، او هغه به هغوئ څروى او هغه به د هغوئ شپونکے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20222, 'Ezekiel 34:24', 'Ezekiel', 34, 24, '&nbsp;زۀ، مالِک خُدائ به د هغوئ خُدائ پاک يم، او زما خِدمتګار داؤد به د دوئ په مينځ کښې شهزاده وى. ما مالِک خُدائ وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20223, 'Ezekiel 34:25', 'Ezekiel', 34, 25, '&nbsp;زۀ به د هغوئ سره د امن لوظ وکړم او د هغه مُلک نه به خطرناک ځناور وشړم، نو هغوئ به په ميرو کښې ژوند کوى او په ځنګلونو کښې به په امن سره اودۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20224, 'Ezekiel 34:26', 'Ezekiel', 34, 26, '&nbsp;زۀ به هغوئ له، او خپل غر نه چاپېره ځايونو له برکت ورکړم. زۀ به په صحيح موسم په هغوئ باران کوم، او دا به د فضل او برکت بارانونه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20225, 'Ezekiel 34:27', 'Ezekiel', 34, 27, '&nbsp;د باغونو ونې به خپلې مېوې کوى او زمکه به خپل فصلونه کوى، او خلق به په خپل مُلک کښې په امن وى. نو بيا به هغوئ پوهه شى چې زۀ مالِک خُدائ يم، کله چې زۀ د هغوئ د غلامۍ جغ مات کړم او د هغه خلقو د لاس نه ورله خلاصون ورکړم چا چې هغوئ غلامان کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20226, 'Ezekiel 34:28', 'Ezekiel', 34, 28, '&nbsp;نور به هغوئ د نورو قومونو د لاسه نۀ لوټ کيږى، او نۀ به يې ځنګلى ځناور خورى. هغوئ به په امن سره ژوند کوى، او هيڅوک به هغوئ نۀ شى يرولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20227, 'Ezekiel 34:29', 'Ezekiel', 34, 29, '&nbsp;زۀ به هغوئ له داسې زمکه ورکړم چې په فصل کولو کښې به مشهوره وى، او هغوئ به نور په دې مُلک کښې د قحط په وجه په تکليف کښې نۀ وى او نۀ به د قومونو مسخرې زغمى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20228, 'Ezekiel 34:30', 'Ezekiel', 34, 30, '&nbsp;نو بيا به هغوئ پوهه شى چې زۀ، مالِک خُدائ د دوئ خُدائ پاک، د دوئ سره يم، او دوئ، د بنى اِسرائيلو قوم، زما خلق دى. مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20229, 'Ezekiel 34:31', 'Ezekiel', 34, 31, '&nbsp;تاسو زما ګډې، زما د څرن د ځائ ګډې، زما خلق يئ، او زۀ ستاسو خُدائ پاک يم. مالِک قادر مطلق خُدائ دا فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20230, 'Ezekiel 35:1', 'Ezekiel', 35, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20231, 'Ezekiel 35:2', 'Ezekiel', 35, 2, '&nbsp;”اے بنى آدمه، خپل مخ په ادوم کښې د سعير د غرۀ خلاف ورواړوه، او د هغۀ خلاف نبوت وکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20232, 'Ezekiel 35:3', 'Ezekiel', 35, 3, '&nbsp;او ورته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى چې، اے د سعير غره زۀ ستا خلاف يم، او زۀ به ستا خلاف خپل لاس دروغزوم او تا به وران ويجاړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20233, 'Ezekiel 35:4', 'Ezekiel', 35, 4, '&nbsp;زۀ به ستا ښارونه په کنډرو بدل کړم او تۀ به شاړ او ويجاړ شې. نو بيا به تۀ پوهه شې چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20234, 'Ezekiel 35:5', 'Ezekiel', 35, 5, '&nbsp;په هغه وخت کښې کله چې ما بنى اِسرائيلو له آخرى سزا ورکوله، نو ستاسو دائمى نفرت هغوئ قصابخانې ته ورسول، په هغه وخت کله چې په هغوئ افت نازل شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20235, 'Ezekiel 35:6', 'Ezekiel', 35, 6, '&nbsp;نو په دې وجه دې زما په خپل ذات قسم وى، مالِک قادر مطلق خُدائ فرمائى چې، زۀ به تاسو قتل و غارت ته حواله کړم او دا به تاسو پسې وى. لکه څنګه چې تاسو د قتل و غارت نه نفرت ونۀ کړو، نو دغه شان قتل و غارت به تاسو پسې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20236, 'Ezekiel 35:7', 'Ezekiel', 35, 7, '&nbsp;زۀ به د سعير غر وران ويجاړ کړم او څوک هم چې په دې ځى راځى ټول به مړۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20237, 'Ezekiel 35:8', 'Ezekiel', 35, 8, '&nbsp;زۀ به ستا غرونه د مړو نه ډک کړم، هغه څوک چې په تُوره مړۀ شوى دى، ستا په غونډو او ستا په درو او ستا په ټولو ګړنګونو کښې به پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20238, 'Ezekiel 35:9', 'Ezekiel', 35, 9, '&nbsp;زۀ به تا د تل دپاره خالى کړم، او ستا ښارونه به بيا آباد نۀ شى. نو بيا به تۀ پوهه شې چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20239, 'Ezekiel 35:10', 'Ezekiel', 35, 10, '&nbsp;ځکه چې تا ووئيل، ”دا دوه مُلکونه، اِسرائيل او يهوداه به زمونږ وى او مونږ به د دوئ جائيدادونه قبضه کړُو،“ اګر کۀ زۀ مالِک خُدائ هم هلته وم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20240, 'Ezekiel 35:11', 'Ezekiel', 35, 11, '&nbsp;نو په دې وجه زما دې په خپل ذات قسم وى، مالِک خُدائ فرمائى، زۀ به تاسو سره د هغه قهر او کينې په مطابق سلوک وکړم، کوم چې تاسو د هغوئ نه په نفرت کولو کښې ښکاره کړو او زۀ به خپل ځان د هغوئ په مينځ کښې څرګند کړم کله چې زۀ ستاسو عدالت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20241, 'Ezekiel 35:12', 'Ezekiel', 35, 12, '&nbsp;نو بيا به تاسو پوهه شئ چې ما مالِک خُدائ هغه بدې خبرې اورېدلې دى کومې چې تاسو د بنى اِسرائيل د غرونو په حقله کړې دى. تاسو ووئيل چې، دا وران او شاړ پراتۀ دى، مونږ ته دې د خوراک په توګه راکړے شوى دى چې وې خورو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20242, 'Ezekiel 35:13', 'Ezekiel', 35, 13, '&nbsp;تا زما خلاف په بې‌پرواهۍ سره لافې او ډيرې خبرې وکړې، او ما دا واورېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20243, 'Ezekiel 35:14', 'Ezekiel', 35, 14, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى، کله چې ټوله دُنيا د خوشحالۍ نه خوند اخلى، زۀ به تاسو شاړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20244, 'Ezekiel 35:15', 'Ezekiel', 35, 15, '&nbsp;ځکه چې تاسو خوشحالى وکړه کله چې د بنى اِسرائيلو د قوم ميراث تباه شو، دغسې سلوک به زۀ تاسو سره وکړم. اے د سعير غره، تۀ او ټول ادوم به وران ويجاړ شې. نو بيا به هر څوک پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20245, 'Ezekiel 36:1', 'Ezekiel', 36, 1, '&nbsp;”اے بنى آدمه، د بنى اِسرائيلو غرونو ته پېشګوئې وکړه او ووايه، اے د بنى اِسرائيل غرونو، د مالِک خُدائ کلام واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20246, 'Ezekiel 36:2', 'Ezekiel', 36, 2, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، ستا دشمن دا پېغور درکولو چې، واه، ستاسو د غرونو پخوانۍ لوړې څوکې زمونږ شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20247, 'Ezekiel 36:3', 'Ezekiel', 36, 3, '&nbsp;نو په دې وجه پېشګوئې وکړه او ورته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، تۀ هغوئ وران ويجاړ کړې، د هرې خوا نه يې وډبولې او تۀ د نورو مُلکونو او قومونو ملکيت او د خندا او غېبت سبب وګرځېدې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20248, 'Ezekiel 36:4', 'Ezekiel', 36, 4, '&nbsp;نو په دې وجه، اے د بنى اِسرائيلو غرونو، د مالِک خُدائ کلام واورئ. مالِک قادر مطلق خُدائ غرونو غونډو او ګړنګونو، او درو ته داسې فرمائى چې، کندو کپرو، وران او تباه شوو ښارونو ته چې د نورو قومونو د لوټ او د خندا سبب ګرځېدلى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20249, 'Ezekiel 36:5', 'Ezekiel', 36, 5, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى، ما په خپل غېرت کښې د نورو قومونو خلاف فېصله وکړه، او خاص د ټول ادوم په خلاف، ځکه چې هغوئ په ډيرې خوشحالۍ او سپک نظر سره زما مُلک خپل ملکيت کړو ترڅو هغوئ د هغۀ د څرن سرسبزه ځائ لوټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20250, 'Ezekiel 36:6', 'Ezekiel', 36, 6, '&nbsp;نو په دې وجه د بنى اِسرائيلو د مُلک په حقله پېشګوئې وکړه او غرونو او غونډو، ګړنګونو او درو ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، ما په خپل غېرتى قهر کښې دې قوم ته دا ووئيل ځکه چې تاسو د نورو قومونو مسخرې تېرې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20251, 'Ezekiel 36:7', 'Ezekiel', 36, 7, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، هغوئ چې څۀ کړى دى نو د هغې په وجه ما قسم وخوړو چې، ستاسو نه ګېرچاپېره مُلکونه به هم دغه شان سپک او بې‌عزته کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20252, 'Ezekiel 36:8', 'Ezekiel', 36, 8, '&nbsp;بلکې تاسو به، اے د بنى اِسرائيل غرونو، څانګې او ډېره مېوه زما د خلقو بنى اِسرائيلو دپاره وکړئ، ځکه چې هغوئ به ډېر زر خپل کور ته راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20253, 'Ezekiel 36:9', 'Ezekiel', 36, 9, '&nbsp;ګورئ، زۀ ستاسو خيال ساتم، او تاسو ته به په ښه سترګه وګورم، او ستا په پټو کښې به بيا خلق کَرل رېبل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20254, 'Ezekiel 36:10', 'Ezekiel', 36, 10, '&nbsp;زۀ به په تا کښې خلق زيات کړم، تر دې چې د بنى اِسرائيل ټول قوم به زيات کړم. ښارونه به بيا آباد شى او وران شوى ځايونه به بيا جوړ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20255, 'Ezekiel 36:11', 'Ezekiel', 36, 11, '&nbsp;زۀ به ستا د سړو او څاروو شمېر زيات کړم، او هغوئ به بارداره او ډېر شى. زۀ به خلق په تا کښې د پخوا په شان په ځائ کړم او د پخوا نه به ډېر برکت درکړم. نو بيا به تۀ په دې پوهه شې چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20256, 'Ezekiel 36:12', 'Ezekiel', 36, 12, '&nbsp;زۀ به خپل خلق بنى اِسرائيل راولم چې په تا باندې وګرځى. هغوئ به په تا قبضه وکړى، او تۀ به د هغوئ ميراث يې، او تۀ به بيا هيڅکله هم هغوئ د خپلو ماشومانو نه، محرومه نۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20257, 'Ezekiel 36:13', 'Ezekiel', 36, 13, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې خلق ستا په حقله وائى چې تۀ خلق لواړ تېروې او خپل قوم د هغوئ د ماشومانو نه محروموې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20258, 'Ezekiel 36:14', 'Ezekiel', 36, 14, '&nbsp;نو د دې نه وروستو به تۀ نور خلق تباه نۀ کړې او نۀ به نور تۀ خپل اوسېدونکى د ماشومانو نه خلاص کړې، مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20259, 'Ezekiel 36:15', 'Ezekiel', 36, 15, '&nbsp;زۀ به نور تا دې ته پرې نۀ ږدم چې د نورو قومونو پيغورونه واورې، او نۀ به نور د قومونو د مسخرو نۀ په تکليف شې او نۀ به تۀ نور د خپلو خلقو دپاره د تيندک سبب يې، مالِک قادر مطلق خُدائ داسې فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20260, 'Ezekiel 36:16', 'Ezekiel', 36, 16, '&nbsp;نو بيا د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20261, 'Ezekiel 36:17', 'Ezekiel', 36, 17, '&nbsp;”اے بنى آدمه، کله چې د بنى اِسرائيلو خلق په خپل مُلک کښې اوسېدل، هغوئ هغه په خپل عمل او چال چلن سره پليت کړو. د هغوئ چال چلن زما په وړاندې لکه د ښځو د مياشتنۍ بيمارۍ په شان ناپاکه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20262, 'Ezekiel 36:18', 'Ezekiel', 36, 18, '&nbsp;نو ما بيا په هغوئ خپل غضب نازل کړو ځکه چې هغوئ په هغه مُلک کښې وينه تويه کړې وه او ځکه چې هغوئ هغه مُلک په خپلو بُتانو سره پليت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20263, 'Ezekiel 36:19', 'Ezekiel', 36, 19, '&nbsp;ما هغوئ په نورو قومونو کښې خوارۀ کړل، او هغوئ په ټولو مُلکونو کښې خوارۀ شوى وُو. ما د هغوئ د چال چلن او عمل په مطابق د هغوئ عدالت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20264, 'Ezekiel 36:20', 'Ezekiel', 36, 20, '&nbsp;هغوئ چې چرته هم په نورو قومونو کښې خوارۀ وارۀ شول، هغوئ زما د مقدس نوم، په دې طريقې سره بې‌حرمتى وکړه، يعنې د هغوئ په حقله نورو قومونو دا وئيل چې، اګر چې هغوئ د مالِک خُدائ خپل خلق دى، خو هغوئ د هغۀ د وطن په پريښودو مجبور شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20265, 'Ezekiel 36:21', 'Ezekiel', 36, 21, '&nbsp;نو ما د خپل مقدس نوم په حقله سوچ کولو، کوم چې د بنى اِسرائيلو په نورو مُلکونو کښې چې چرته هم هغوئ رسېدلى وُو سپک يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20266, 'Ezekiel 36:22', 'Ezekiel', 36, 22, '&nbsp;نو په دې وجه بنى اِسرائيلو ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، اے بنى اِسرائيلو دا ستاسو دپاره نۀ دى کوم څيزونه چې زۀ کوم، خو دا زما د مقدس نوم په خاطر دى، د کوم چې تاسو په نورو قومونو کښې بې‌حرمتى وکړه چرته چې هم لاړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20267, 'Ezekiel 36:23', 'Ezekiel', 36, 23, '&nbsp;زۀ به د خپل عظيم نوم قدوسيت ښکاره کړم، د کوم چې تاسو د نورو قومونو په مينځ کښې بې‌حرمتى وکړه. مالِک قادر مطلق خُدائ فرمائى، کله چې زۀ د هغوئ د سترګو د وړاندې خپل ځان مقدس ښکاره کړم نو بيا به هغه قومونه په دې وپوهيږى چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20268, 'Ezekiel 36:24', 'Ezekiel', 36, 24, '&nbsp;ځکه چې زۀ به تاسو د نورو قومونو نه راغونډ کړم، زۀ به تاسو د ټولو مُلکونو نه راجمع کړم او خپل مُلک ته به مو واپس راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20269, 'Ezekiel 36:25', 'Ezekiel', 36, 25, '&nbsp;زۀ به پاکې اوبۀ په تاسو وشيندم، نو تاسو به پاک شئ. زۀ به تاسو د خپلو ټولو حرام کارو او بُتانو نه پاک کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20270, 'Ezekiel 36:26', 'Ezekiel', 36, 26, '&nbsp;زۀ به تاسو له نوے زړۀ درکړم او په تاسو کښې به نوے روح واچوم. زۀ به تاسو نه دا سخت زړۀ لرى کړم او نرم زړۀ به درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20271, 'Ezekiel 36:27', 'Ezekiel', 36, 27, '&nbsp;زۀ به په تاسو کښې خپل روح واچوم او خپلې تابعدارۍ طرف ته به ستاسو پام راوګرځوم چې زما په اصُولو عمل کوئ او زما د حکمونو په ساتلو کښې احتياط کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20272, 'Ezekiel 36:28', 'Ezekiel', 36, 28, '&nbsp;نو تاسو به بيا په هغه مُلک کښې اوسېږئ کوم چې ما ستاسو پلار نيکۀ له ورکړے وو. تاسو به زما خلق يئ، او زۀ به ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20273, 'Ezekiel 36:29', 'Ezekiel', 36, 29, '&nbsp;زۀ به تاسو د خپلو ټولو پليتو نه بچ کړم. زۀ به د غلو فصلونو له برکت ورکړم او په تاسو به نور قحط نۀ راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20274, 'Ezekiel 36:30', 'Ezekiel', 36, 30, '&nbsp;زۀ به ستاسو د ونو مېوې او د پټو فصلونه زيات کړم، ترڅو تاسو د نورو قومونو په مينځ کښې د قحط په وجه شرمنده نۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20275, 'Ezekiel 36:31', 'Ezekiel', 36, 31, '&nbsp;نو بيا به تاسو ته خپل حرام کارونه او غلط حرکتونه در په ياد شى، او بيا به تۀ په خپلو حرامو کارونو او ګناهونو د پښېمانۍ احساس وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20276, 'Ezekiel 36:32', 'Ezekiel', 36, 32, '&nbsp;زۀ غواړم چې تاسو په دې خبره پوهه شئ چې دا زۀ ستاسو دپاره نۀ کوم چې ګنې تاسو د دې حقدار يئ، مالِک قادر مطلق خُدائ فرمائى. اے بنى اِسرائيلو، د خپلو عملونو او کردار په وجه په شرمونو وشرمېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20277, 'Ezekiel 36:33', 'Ezekiel', 36, 33, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، په کومه ورځ چې زۀ تاسو د خپلو ټولو ګناهونو نه پاک کړم، زۀ به ستاسو ښارونه بيا ودان، او دوباره به ستاسو کنډرې آبادې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20278, 'Ezekiel 36:34', 'Ezekiel', 36, 34, '&nbsp;هغه زمکه چې شاړه او بنجره وه په کومه به چې څوک هم تېرېدل او هغوئ به ليدله چې شاړه به پرته وه دوباره به په هغه زمکه کښې کرونده وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20279, 'Ezekiel 36:35', 'Ezekiel', 36, 35, '&nbsp;او خلق به داسې وائى چې، دا کومه زمکه چې شاړه پرته وه اوس ترې باغِ عدن جوړ شوے دے. او کوم ښارونه چې کنډرې پراتۀ وُو، شاړ او تباه شوى وُو، اوس مضبوط او بيا آباد شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20280, 'Ezekiel 36:36', 'Ezekiel', 36, 36, '&nbsp;نو بيا هغه قومونه کوم چې ستاسو په خوا او شا کښې پاتې دى هغوئ به په دې پوهه شى چې ما مالِک خُدائ هغه څۀ آباد کړل کوم چې وران ويجاړ شوى وُو او هغه څۀ مې وکرل کوم چې اوچ او شاړ شوى وُو. ما مالِک خُدائ وفرمائيل، او زۀ به يې وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20281, 'Ezekiel 36:37', 'Ezekiel', 36, 37, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، يو ځل بيا به د بنى اِسرائيلو درخواست ته توجو وکړم او د هغوئ دپاره به دا‎ وکړم، زۀ به د ګډو په شان د هغوئ د خلقو شمېره زياته کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20282, 'Ezekiel 36:38', 'Ezekiel', 36, 38, '&nbsp;زۀ به هغوئ دومره زيات کړم لکه څومره رَمې به چې د نذارانو اخترونو دپاره يروشلم ته راتللې. نو هم داسې به وران ويجاړ ښارونه د خلقو د رَمو نه ډک کړم. نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20283, 'Ezekiel 37:1', 'Ezekiel', 37, 1, '&nbsp;د مالِک خُدائ لاس په ما وو، او هغۀ زۀ د مالِک خُدائ د روح په وسيله رابهر کړم او د يوې درې مينځ کښې يې ودرولم، او دا د هډوکو نه ډکه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20284, 'Ezekiel 37:2', 'Ezekiel', 37, 2, '&nbsp;هغۀ زۀ د هغوئ په مينځ کښې مخکښې وروستو وګرځولم، او ما هلته ډېر زيات هډُوکى د هغې درې په زمکه وليدل. او هغه هډُوکى ډېر اوچ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20285, 'Ezekiel 37:3', 'Ezekiel', 37, 3, '&nbsp;هغۀ ما نه تپوس وکړو، ”اے بنى آدمه، ولې دا هډُوکى ژوندى کېدے شى؟“ نو ما ورته په جواب کښې ووئيل، ”اے مالِک قادر مطلق خُدايه، صرف تۀ په دې پوهېږې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20286, 'Ezekiel 37:4', 'Ezekiel', 37, 4, '&nbsp;بيا هغۀ ما ته وفرمائيل چې، ”دې هډوکو ته پېشګوئې وکړه او ورته ووايه، اوچو هډوکو، د مالِک خُدائ کلام واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20287, 'Ezekiel 37:5', 'Ezekiel', 37, 5, '&nbsp;مالِک قادر مطلق خُدائ دې هډوکو ته دا فرمائى چې، ګوره زۀ به په تاسو کښې ساه واچوم، او تاسو به راژوندى شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20288, 'Ezekiel 37:6', 'Ezekiel', 37, 6, '&nbsp;زۀ به په تاسو باندې پلې، غوښه راولم او په څرمن کښې به مو پټ کړم، زۀ به په تاسو کښې ساه واچوم، او تاسو به راژوندى شئ. نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ ‎يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20289, 'Ezekiel 37:7', 'Ezekiel', 37, 7, '&nbsp;نو ما هم هغه شان پېشګوئې وکړه څنګه چې ما ته حکم شوے وو. او کله چې ما پېشګوئې کوله، نو ناګهانه بيا ما د هډوکو کړسار او شور واورېدو، او هډُوکى خپلو کښې يو بل سره يوځائ شول او ډانچې ورنه جوړې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20290, 'Ezekiel 37:8', 'Ezekiel', 37, 8, '&nbsp;نو بيا ما وليدل چې، پلې او غوښې په هغوئ باندې راغلې او بيا په څرمن کښې پټ شول، خو په هغوئ کښې ساه نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20291, 'Ezekiel 37:9', 'Ezekiel', 37, 9, '&nbsp;بيا هغۀ ما ته وفرمائيل، ”ساه ته پېشګوئې وکړه، پېشګوئې وکړه، اے بنى آدمه، او ورته ووايه، مالِک قادر مطلق خُدائ دا فرمائى، اے ساه، د څلورو طرفونو هواګانو نه راشه، او په دې قتل شوو کښې ننوځه چې هغوئ راژوندى شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20292, 'Ezekiel 37:10', 'Ezekiel', 37, 10, '&nbsp;نو ما هم هغه شان پېشګوئې وکړه څنګه چې هغۀ ما ته حکم وکړو، او ساه په هغوئ کښې راغله، هغوئ راژوندى شول او په خپلو پښو ودرېدل، يو ډېر لوئ لښکر ترې جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20293, 'Ezekiel 37:11', 'Ezekiel', 37, 11, '&nbsp;بيا هغۀ ما ته وفرمائيل، ”اے بنى آدمه، دا هډوکى د ټول بنى اِسرائيلى قوم دى. هغوئ وائى چې، زمونږ هډوکى اوچ شوى دى او زمونږ اُميد ختم شوے دے، او مونږ ختم شوى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20294, 'Ezekiel 37:12', 'Ezekiel', 37, 12, '&nbsp;نو په دې وجه پېشګوئې وکړه او هغوئ ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، ګورئ، اے زما خلقو، زۀ به ستاسو قبرونه پرانيزم او د هغوئ نه به مو بهر راوکاږم او زۀ به تاسو واپس د اِسرائيل زمکې ته راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20295, 'Ezekiel 37:13', 'Ezekiel', 37, 13, '&nbsp;نو بيا به تاسو زما خلق په دې خبره پوهه شئ چې زۀ مالِک خُدائ يم، کله چې زۀ ستاسو قبرونه پرانيزم او تاسو د دې نه راوکاږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20296, 'Ezekiel 37:14', 'Ezekiel', 37, 14, '&nbsp;زۀ به خپل روح په تاسو کښې واچوم او تاسو به ژوندى شئ، او زۀ به تاسو په خپله زمکه آباد کړم. بيا به تاسو په دې پوهه شئ چې ما مالِک خُدائ څۀ فرمائيلى وُو، هغه ما وکړل. مالِک خُدائ داسې فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20297, 'Ezekiel 37:15', 'Ezekiel', 37, 15, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20298, 'Ezekiel 37:16', 'Ezekiel', 37, 16, '&nbsp;”اے بنى آدمه، يو امسا راواخله او په هغې وليکه چې دا د يهوداه او هغۀ سره ولاړې قبيلې دى. بيا يو بله امسا راواخله او په هغې دا وليکه چې، د اِفرائيم امسا، دا د يوسف او د ټولو بنى اِسرائيلو د شمالى قبيلو ده چې ورسره ولاړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20299, 'Ezekiel 37:17', 'Ezekiel', 37, 17, '&nbsp;بيا هغوئ په يوه امسا کښې داسې يو ځائ کړه چې ستا په لاس کښې هغوئ يو بل سره ونښلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20300, 'Ezekiel 37:18', 'Ezekiel', 37, 18, '&nbsp;کله چې ستا د مُلک خلق ستا نه تپوس وکړى چې، ولې تۀ به مونږ ته دا نۀ وائې چې د دې څۀ مطلب دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');